<?php
require_once __DIR__ . '/lib/blog.php';
$db = blog_db();
$slug = trim($_GET['slug'] ?? '');
$blog = null;
if ($db && $slug !== '') {
    $stmt = $db->prepare("SELECT b.*, a.name AS author_name, a.bio AS author_bio, a.image_url AS author_image, a.page_url AS author_url, GROUP_CONCAT(c.name SEPARATOR ', ') AS category_names FROM blogs b LEFT JOIN blog_authors a ON a.id=b.author_id LEFT JOIN blog_category_map m ON m.blog_id=b.id LEFT JOIN blog_categories c ON c.id=m.category_id WHERE b.slug=? AND b.status='published' AND (b.published_at IS NULL OR b.published_at<=NOW()) GROUP BY b.id");
    $stmt->execute([$slug]); $blog = $stmt->fetch();
    if (!$blog) { $redirect = $db->prepare('SELECT new_slug FROM blog_redirects WHERE old_slug=? LIMIT 1'); $redirect->execute([$slug]); if ($new = $redirect->fetchColumn()) { header('Location: ' . SITE_URL . '/blog/' . rawurlencode($new), true, 301); exit; } }
}
if (!$blog && $slug !== '') { http_response_code(404); }
$GLOBALS['current_blog'] = $blog;
ob_start('blog_customize_output');
$description = $blog['meta_description'] ?? 'Read insights, tips, and trends in online education from Amity Online University.';
$title = $blog['meta_title'] ?? 'Blog - Amity Online University';
$canonical = $blog ? blog_public_url($blog['slug']) : SITE_URL . '/blog';
function blog_cards($db) { if (!$db) return []; $s=$db->query("SELECT b.slug,b.title,b.excerpt,b.feature_image,b.feature_image_alt,b.published_at,a.name author_name FROM blogs b LEFT JOIN blog_authors a ON a.id=b.author_id WHERE b.status='published' AND b.published_at<=NOW() ORDER BY b.published_at DESC LIMIT 12"); return $s->fetchAll(); }
$posts = $blog ? [] : blog_cards($db);
$related = [];
if ($blog && $db) { $s=$db->prepare("SELECT b.slug,b.title,b.excerpt,b.feature_image,b.feature_image_alt FROM blogs b WHERE b.status='published' AND b.id<>? AND b.published_at<=NOW() ORDER BY b.published_at DESC LIMIT 3"); $s->execute([$blog['id']]); $related=$s->fetchAll(); }
$headings=[]; if ($blog && !empty($blog['toc_enabled'])) { preg_match_all('/<h([2-4])([^>]*)>(.*?)<\/h\1>/is', $blog['content'], $matches, PREG_SET_ORDER); foreach ($matches as $i=>$match) { $text=trim(strip_tags($match[3])); $id=blog_slug($text); $headings[]=['level'=>(int)$match[1],'text'=>$text,'id'=>$id.'-'.$i]; } }
$renderedContent = $blog ? blog_safe_content($blog['content']) : '';
if ($blog && $headings) { $headingIndex = 0; $renderedContent = preg_replace_callback('/<h([2-4])([^>]*)>(.*?)<\/h\1>/is', function ($match) use (&$headingIndex, $headings) { $id = $headings[$headingIndex++]['id']; return '<h' . $match[1] . $match[2] . ' id="' . blog_e($id) . '">' . $match[3] . '</h' . $match[1] . '>'; }, $renderedContent); }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="<?php echo blog_e($description); ?>"><meta name="robots" content="<?php echo $blog ? 'index,follow' : 'noindex,follow'; ?>"><link rel="canonical" href="<?php echo blog_e($canonical); ?>"><meta property="og:type" content="article"><meta property="og:title" content="<?php echo blog_e($title); ?>"><meta property="og:description" content="<?php echo blog_e($description); ?>"><meta property="og:url" content="<?php echo blog_e($canonical); ?>"><?php if ($blog && $blog['feature_image']): ?><meta property="og:image" content="<?php echo blog_e($blog['feature_image']); ?>"><?php endif; ?><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="<?php echo blog_e($title); ?>"><meta name="twitter:description" content="<?php echo blog_e($description); ?>"><title><?php echo blog_e($title); ?></title><link rel="stylesheet" href="css/styles.css"><style>
.blog-shell{max-width:1100px;margin:auto;padding:2rem 1rem}.blog-crumbs{font-size:.9rem;color:#667085;margin:1rem 0}.blog-hero{padding:3rem 0 2rem}.blog-hero h1{max-width:850px;font-size:clamp(2rem,5vw,4rem)}.blog-excerpt{font-size:1.15rem;max-width:760px}.blog-image{width:100%;max-height:560px;object-fit:cover;border-radius:10px}.blog-layout{display:grid;grid-template-columns:240px minmax(0,1fr);gap:3rem;margin-top:3rem}.blog-toc{position:sticky;top:1rem;align-self:start;border-left:3px solid var(--gold);padding-left:1rem}.blog-toc a{display:block;padding:.3rem 0;color:var(--navy-blue)}.blog-toc .toc-3{padding-left:1rem;font-size:.9rem}.blog-content{font-size:1.08rem;line-height:1.85}.blog-content h2{margin-top:2.5rem}.blog-content h3{margin-top:1.8rem}.blog-content img{max-width:100%;height:auto}.blog-content table{display:block;overflow-x:auto;border-collapse:collapse}.blog-content th,.blog-content td{border:1px solid #ccd3df;padding:.6rem}.author-box,.lead-box{margin-top:3rem;padding:1.5rem;background:#f5f7fb;border-radius:8px}.blog-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1.2rem}.blog-card img{width:100%;aspect-ratio:1200/628;object-fit:cover;border-radius:6px}.blog-card{border:1px solid #e2e7ef;padding:1rem;border-radius:8px}.lead-box form{display:grid;gap:.7rem;max-width:500px}.lead-box input,.lead-box select{padding:.75rem;border:1px solid #ccd3df;border-radius:5px}@media(max-width:760px){.blog-layout{display:block}.blog-toc{position:static;margin-bottom:2rem}.blog-grid{grid-template-columns:1fr}}
</style></head><body><header class="header"><nav class="nav container"><a href="/" class="logo">Amity<span>Online</span></a><ul class="nav-menu" id="navMenu"><li><a href="/" class="nav-link">Home</a></li><li><a href="programs" class="nav-link">Programs</a></li><li><a href="about" class="nav-link">About Us</a></li><li><a href="blog" class="nav-link">Blog</a></li><li><a href="contact" class="nav-link">Contact</a></li></ul><button class="mobile-toggle" id="mobileToggle" aria-label="Open menu"><span></span><span></span><span></span></button></nav></header><main class="blog-shell"><nav class="blog-crumbs" aria-label="Breadcrumb"><a href="/">Home</a> &rarr; <a href="/blog">Blog</a><?php if ($blog): ?> &rarr; <span><?php echo blog_e($blog['title']); ?></span><?php endif; ?></nav><?php if ($blog): ?><article><header class="blog-hero"><p class="blog-crumbs"><?php echo blog_e($blog['category_names'] ?: 'Online education'); ?> &middot; <?php echo blog_e(date('F j, Y', strtotime($blog['published_at']))); ?></p><h1><?php echo blog_e($blog['title']); ?></h1><p class="blog-excerpt"><?php echo blog_e($blog['excerpt']); ?></p><p>By <strong><?php echo blog_e($blog['author_name'] ?: 'Amity Online Editorial Team'); ?></strong><?php if ($blog['author_url']): ?> &middot; <a href="<?php echo blog_e($blog['author_url']); ?>">Author profile</a><?php endif; ?></p></header><?php if ($blog['feature_image']): ?><img class="blog-image" src="<?php echo blog_e($blog['feature_image']); ?>" alt="<?php echo blog_e($blog['feature_image_alt']); ?>" width="1200" height="628"><?php endif; ?><div class="blog-layout"><?php if ($headings): ?><nav class="blog-toc" aria-label="In this article"><strong>In this article</strong><?php foreach($headings as $h): ?><a class="toc-<?php echo $h['level']; ?>" href="#<?php echo blog_e($h['id']); ?>"><?php echo blog_e($h['text']); ?></a><?php endforeach; ?></nav><?php endif; ?><div class="blog-content"><?php echo blog_safe_content($blog['content']); ?></div></div><?php if ($blog['author_bio']): ?><section class="author-box"><h2>About the author</h2><p><?php echo blog_e($blog['author_bio']); ?></p></section><?php endif; ?><?php if (!empty($blog['lead_form_enabled'])): ?><section class="lead-box"><h2>Talk to an admissions advisor</h2><form action="submit-form.php" method="post"><input name="name" placeholder="Name" required><input name="phone" placeholder="Phone number" required><input name="email" type="email" placeholder="Email" required><select name="course" required><option value="">Select a course</option><option value="MBA">MBA</option><option value="BBA">BBA</option><option value="BCA">BCA</option><option value="MCA">MCA</option></select><label><input name="consent" type="checkbox" value="1" required> I agree to be contacted</label><input type="hidden" name="formType" value="enquire"><button class="btn btn-primary">Request information</button></form></section><?php endif; ?><?php if ($related): ?><section><h2>Related articles</h2><div class="blog-grid"><?php foreach($related as $item): ?><article class="blog-card"><?php if($item['feature_image']): ?><img src="<?php echo blog_e($item['feature_image']); ?>" alt="<?php echo blog_e($item['feature_image_alt']); ?>" loading="lazy" width="1200" height="628"><?php endif; ?><h3><a href="/blog/<?php echo rawurlencode($item['slug']); ?>"><?php echo blog_e($item['title']); ?></a></h3><p><?php echo blog_e($item['excerpt']); ?></p></article><?php endforeach; ?></div></section><?php endif; ?></article><?php else: ?><header class="blog-hero"><p class="eyebrow">AMITY ONLINE JOURNAL</p><h1>Ideas for learning, careers and what comes next.</h1><p class="blog-excerpt">Practical insights for students and working professionals building their next chapter.</p></header><section><div class="blog-grid"><?php foreach($posts as $item): ?><article class="blog-card"><?php if($item['feature_image']): ?><img src="<?php echo blog_e($item['feature_image']); ?>" alt="<?php echo blog_e($item['feature_image_alt']); ?>" loading="lazy" width="1200" height="628"><?php endif; ?><p><?php echo blog_e(date('M j, Y',strtotime($item['published_at']))); ?> &middot; <?php echo blog_e($item['author_name'] ?: 'Amity Online'); ?></p><h2><a href="/blog/<?php echo rawurlencode($item['slug']); ?>"><?php echo blog_e($item['title']); ?></a></h2><p><?php echo blog_e($item['excerpt']); ?></p></article><?php endforeach; ?></div><?php if (!$posts): ?><p>No published articles yet.</p><?php endif; ?></section><?php endif; ?></main><script src="js/script.js"></script><?php if ($blog): ?><script type="application/ld+json"><?php echo json_encode(['@context'=>'https://schema.org','@type'=>'Article','headline'=>$blog['title'],'description'=>$blog['excerpt'],'url'=>$canonical,'image'=>$blog['feature_image'] ? [$blog['feature_image']] : [],'datePublished'=>$blog['published_at'],'dateModified'=>$blog['last_updated_at'],'author'=>['@type'=>'Person','name'=>$blog['author_name'] ?: 'Amity Online Editorial Team'],'mainEntityOfPage'=>['@type'=>'WebPage','@id'=>$canonical]], JSON_UNESCAPED_SLASHES); ?></script><?php endif; ?></body></html>
